'use strict';
const V16TOPICS=[['departure','计划出发提醒'],['feedback','灾情核验与回复'],['tasks','任务进度'],['giving','模拟公益用途反馈'],['software','软件维护回复']];
const V16CHANNELS=[['inapp','站内消息','保存到下方消息记录'],['browser','浏览器通知','需要授权；页面打开时发送'],['sound','提示音','短提示音，浏览器可能限制播放']];
function v16Channels(){return Array.isArray(V2.settings.channels)?V2.settings.channels:['inapp']}
function v16Topics(){return Array.isArray(V2.settings.topics)?V2.settings.topics:V16TOPICS.map(x=>x[0])}
function v16BrowserPermission(){return typeof Notification==='undefined'?'浏览器不支持':Notification.permission==='granted'?'已授权':Notification.permission==='denied'?'已被浏览器阻止':'尚未授权'}
function v16QuietAt(time=new Date()){if(!V2.settings.quiet)return false;const clock=new Date(time.getTime()+8*3600000),minute=clock.getUTCHours()*60+clock.getUTCMinutes(),parse=s=>{const [h,m]=s.split(':').map(Number);return h*60+m},start=parse(V2.settings.quietStart||'22:00'),end=parse(V2.settings.quietEnd||'07:00');return start===end?true:start<end?minute>=start&&minute<end:minute>=start||minute<end}
function v16ReminderSettings(){const enabled=!!V2.settings.alert,rows=v9StoreBase('sy-v16-notifications').slice().reverse(),channels=v16Channels(),topics=v16Topics();return `<div class="v16reminders"><div class="row"><h3>提醒设置</h3><span class="tag ${enabled?'green':'gray'}">${enabled?'提醒已开启':'不提醒'}</span></div><div class="v16remindmode"><label>提醒偏好<select id="v15-reminder"><option value="0" ${!enabled?'selected':''}>不提醒</option>${[15,30,60].map(n=>`<option value="${n}" ${enabled&&Number(V2.settings.lead||15)===n?'selected':''}>开启提醒 · 出发前${n}分钟</option>`).join('')}</select></label><small>${enabled?'已选的非出发类消息在状态更新后提醒。':'提醒已关闭；不会发送通知或播放提示音。'}</small></div><fieldset ${!enabled?'disabled':''}><legend>提醒方式 · 可多选</legend><div class="v16channelgrid">${V16CHANNELS.map(([id,t,desc])=>`<label class="v16channel"><input type="checkbox" data-remind-channel="${id}" ${channels.includes(id)?'checked':''}><span><b>${t}</b><small>${desc}</small></span></label>`).join('')}</div><div class="v16permission"><span>浏览器通知：${v16BrowserPermission()}</span>${typeof Notification!=='undefined'&&Notification.permission==='denied'?'<small>通知已被浏览器阻止。如需开启，可在浏览器网站权限中调整；也可使用站内消息。</small>':'<button type="button" data-v16="browser-permission">申请浏览器通知授权</button>'}</div><p class="muted">短信、邮件与手机推送暂未接入，不显示为已发送。</p></fieldset><fieldset ${!enabled?'disabled':''}><legend>提醒内容</legend><div class="v16topics">${V16TOPICS.map(([id,t])=>`<label><input type="checkbox" data-remind-topic="${id}" ${topics.includes(id)?'checked':''}> ${t}</label>`).join('')}</div></fieldset><div class="v16quiet"><label><input id="v16-quiet" type="checkbox" ${V2.settings.quiet?'checked':''} ${!enabled?'disabled':''}> 开启免打扰</label><label>开始<input id="v16-quiet-start" type="time" value="${esc(V2.settings.quietStart||'22:00')}" ${!enabled||!V2.settings.quiet?'disabled':''}></label><label>结束<input id="v16-quiet-end" type="time" value="${esc(V2.settings.quietEnd||'07:00')}" ${!enabled||!V2.settings.quiet?'disabled':''}></label><small>北京时间；免打扰期间只保留消息记录。</small></div><div class="chips"><button data-v16="test-reminder" ${!enabled?'disabled':''}>测试已选提醒方式</button><button data-v16="read-reminders">将消息标为已读</button></div><p class="v16remindscope">提醒在页面打开时运行。关闭页面后的自动推送尚未接入；历史场景不自动触发真实出发提醒。</p><details class="v16inbox" ${rows.length?'open':''}><summary>消息记录 · ${rows.filter(r=>!r.read).length}条未读</summary>${rows.slice(0,10).map(r=>`<article><div class="row"><b data-original>${esc(r.title)}</b><small>${esc(dateText(r.time))}</small></div><p data-original>${esc(r.body)}</p><small>${r.test?'手动测试':r.context==='history'?'历史演示更新':'本浏览器更新'}${r.quiet?' · 免打扰，未播放声音或弹出通知':''}</small></article>`).join('')||'<p>开启提醒后可测试，消息记录会保留在这里。</p>'}</details></div>`}
function v16PlaySound(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return false;const c=new Audio(),osc=c.createOscillator(),gain=c.createGain();osc.connect(gain);gain.connect(c.destination);osc.frequency.value=660;gain.gain.setValueAtTime(.06,c.currentTime);gain.gain.exponentialRampToValueAtTime(.001,c.currentTime+.25);osc.start();osc.stop(c.currentTime+.25);osc.onended=()=>c.close();return true}catch{return false}}
function v16Notify(topic,title,body,{test=false}={}){if(!V2.settings.alert||!test&&!v16Topics().includes(topic)||!v16Channels().length)return null;const quiet=!test&&v16QuietAt(),row={id:vId(),topic,title,body,time:new Date().toISOString(),context:V9.active?'history':'now',test,quiet,read:false},rows=v9StoreBase('sy-v16-notifications');rows.push(row);if(!v9SaveBase('sy-v16-notifications',rows.slice(-100)))return null;if(!quiet&&V3.role==='user'){const channels=v16Channels();if(channels.includes('inapp'))toast(title+'：'+body);if(channels.includes('sound'))v16PlaySound();if(channels.includes('browser')&&typeof Notification!=='undefined'&&Notification.permission==='granted'){try{new Notification(title,{body,tag:row.id})}catch{}}}return row}
function v16CheckDepartures(now=new Date()){if(!V2.settings.alert||!v16Topics().includes('departure')||V9.active||V2.mode!=='now'||V3.role!=='user')return;const seen=v9StoreBase('sy-v16-departure-notices')||[],lead=Number(V2.settings.lead||15)*60000;let changed=false;for(const p of V2.plans){if(p.mode!=='now'||p.blocked||p.unavailable||!p.planned)continue;const when=v11Date(p.planned).getTime(),key=p.id+'@'+p.planned;if(!Number.isFinite(when)||when<now.getTime()||when-now.getTime()>lead||seen.includes(key))continue;const row=v16Notify('departure','计划出发提醒',`${p.leg==='return'?'返程':'去程'} ${p.origin} → ${p.destination}，计划${dateText(p.planned)}出发。`);if(row){seen.push(key);changed=true}}if(changed)v9SaveBase('sy-v16-departure-notices',seen.slice(-200))}
document.addEventListener('change',e=>{const t=e.target,id=t.id,channel=t.dataset?.remindChannel,topic=t.dataset?.remindTopic;if(id!=='v15-reminder'&&!channel&&!topic&&!id.startsWith('v16-quiet'))return;if(channel&&!V16CHANNELS.some(c=>c[0]===channel)||topic&&!V16TOPICS.some(x=>x[0]===topic))return;e.stopImmediatePropagation();if(id==='v15-reminder'){V2.settings.alert=Number(t.value)>0;if(V2.settings.alert)V2.settings.lead=Number(t.value)}if(channel)V2.settings.channels=t.checked?[...new Set([...v16Channels(),channel])]:v16Channels().filter(c=>c!==channel);if(topic)V2.settings.topics=t.checked?[...new Set([...v16Topics(),topic])]:v16Topics().filter(c=>c!==topic);if(id==='v16-quiet')V2.settings.quiet=t.checked;if(id==='v16-quiet-start'||id==='v16-quiet-end'){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.value))return;V2.settings[id==='v16-quiet-start'?'quietStart':'quietEnd']=t.value}save('sy-v2-settings',V2.settings);vRender()},true);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-v16]');if(!b)return;const a=b.dataset.v16;if(a==='browser-permission'){if(typeof Notification==='undefined')return toast('当前浏览器不支持系统通知，可使用站内消息与提示音');if(Notification.permission==='denied')return toast('通知已被浏览器阻止，请在浏览器网站设置中调整');try{await Notification.requestPermission();vRender()}catch{toast('浏览器通知授权未完成')}return}if(a==='test-reminder'){if(!V2.settings.alert)return toast('请先开启提醒');if(!v16Channels().length)return toast('请至少选择一种提醒方式');v16Notify('test','深雨知路 · 测试提醒','这是一条手动测试消息，没有新增灾情或真实支付。',{test:true});vRender();return}if(a==='read-reminders'){v9SaveBase('sy-v16-notifications',v9StoreBase('sy-v16-notifications').map(r=>({...r,read:true})));vRender()}});
if(typeof setInterval==='function')setInterval(()=>v16CheckDepartures(),30000);
